(function(){console.log("Orbit Wallet content script injector loaded");window.addEventListener("message",async e=>{if(e.source!==window||e.data.type!=="ORBIT_REQUEST")return;const{requestId:n,method:o,params:d,origin:r}=e.data;console.log("Content script received request:",o,"from",r);try{const t=await chrome.runtime.sendMessage({type:"RPC_REQUEST",request:{id:n,jsonrpc:"2.0",method:o,params:d},origin:r});window.postMessage({type:"ORBIT_RESPONSE",responseId:n,result:t.result,error:t.error?.message},"*")}catch(t){console.error("Error handling request:",t),window.postMessage({type:"ORBIT_RESPONSE",responseId:n,error:t.message||"Unknown error"},"*")}});chrome.runtime.onMessage.addListener(e=>{e.type==="CHAIN_CHANGED"?window.postMessage({type:"ORBIT_EVENT",eventType:"chainChanged",data:e.chainId},"*"):e.type==="ACCOUNTS_CHANGED"?window.postMessage({type:"ORBIT_EVENT",eventType:"accountsChanged",data:e.accounts},"*"):e.type==="DISCONNECT"&&window.postMessage({type:"ORBIT_EVENT",eventType:"disconnect",data:null},"*")});function s(){const e=document.createElement("script");e.src=chrome.runtime.getURL("content/inpage.js"),e.onload=()=>{e.remove()},(document.head||document.documentElement).appendChild(e)}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",s):s();console.log("Orbit Wallet content script injector ready");
})()
